// prepare global namespace
if (!window.wcp) window.wcp = {};

// set WCP version globally
if (window.wcp.version !== undefined && window.wcp.version !== '0.10.4') {
  console.warn('[wcp] 0.10.4: Another version (' + window.wcp.version + ') has already been loaded.');
} else window.wcp.version = '0.10.4';

// set breakpoints globally
window.wcp.breakpoints = {
  xs: 480,
  sm: 768,
  md: 992,
  lg: 1200,
  xl: 1600,
};

